if _libzip then
    M.LIBZIP_OPEN_FLAGS.CREATE = _libzip.CREATE -- Create the archive if it does not exist.
    M.LIBZIP_OPEN_FLAGS.EXCL = _libzip.EXCL -- Error if archive already exists.
    M.LIBZIP_OPEN_FLAGS.CHECKCONS = _libzip.CHECKCONS -- Perform additional consistency checks on the archive, and error if they fail.
end

M.LIBZIP_ENTRY_OPEN_FLAG = {}
if _libzip then
    M.LIBZIP_ENTRY_OPEN_FLAG.FL_COMPRESSED = _libzip.FL_COMPRESSED -- Read the compressed data. Otherwise the data is uncompressed by file:read()
    M.LIBZIP_ENTRY_OPEN_FLAG.FL_UNCHANGED = _libzip.FL_UNCHANGED --Read the original data from the zip archive, ignoring any changes made to the file.
    M.LIBZIP_ENTRY_OPEN_FLAG.FL_NOCASE = _libzip.FL_NOCASE -- Ignore case distinction
    M.LIBZIP_ENTRY_OPEN_FLAG.FL_NODIR = _libzip.FL_NODIR -- Ignore directory part of file name in archive.
